func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/healthz", wrapper.GetLiveness)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/readyz", wrapper.GetReadiness)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/register", wrapper.Register)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/login", wrapper.Login)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/logout", wrapper.Logout)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/refresh", wrapper.Refresh)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/email/request", wrapper.RequestTokenEmail)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/email/verify", wrapper.ConfirmEmailVerification)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/password/reset", wrapper.ConfirmPasswordReset)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/magic/consume", wrapper.ConsumeMagicLink)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/otp/consume", wrapper.ConsumeOTP)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/me/profile", wrapper.GetProfile)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/me/profile", wrapper.SaveProfile)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/me/documents", wrapper.ListDocuments)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/me/documents", wrapper.StartDocumentUpload)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/me/documents/{documentId}/complete", wrapper.CompleteDocumentUpload)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/me/documents/{documentId}/abort", wrapper.AbortDocumentUpload)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/me/documents/{documentId}", wrapper.DeleteDocument)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/me/documents/{documentId}/facts", wrapper.ListDocumentFacts)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/me/facts/{factId}/review", wrapper.ReviewFact)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/catalog/disciplines", wrapper.ListDisciplines)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/catalog/roles", wrapper.ListRoles)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/catalog/interview-shapes", wrapper.ListInterviewShapes)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/catalog/personas", wrapper.ListPersonas)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/interviews", wrapper.CreateInterview)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/me", wrapper.GetCurrentUser)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/me/memberships", wrapper.ListMemberships)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/me/active-tenant", wrapper.SetActiveTenant)

	return m
}

